"""
L0 Property-Based Tests: Serialization/Deserialization.
Verifies roundtrip and schema conformance for wire protocol messages.
"""
import hypothesis.strategies as st
from hypothesis import given, settings
import pytest
import json

from swarm_components.wire_protocol import (
    encode_message,
    decode_message,
    MessageSchemaError,
)

# --- Strategies for message fields ---
node_id_strategy = st.integers(min_value=0, max_value=2**32 - 1)
timestamp_strategy = st.integers(min_value=0, max_value=2**63 - 1)
payload_strategy = st.dictionaries(
    keys=st.text(min_size=1, max_size=32),
    values=st.one_of(st.integers(), st.text(), st.booleans(), st.floats(allow_nan=False)),
    max_size=10,
)

message_strategy = st.fixed_dictionaries({
    "node_id": node_id_strategy,
    "timestamp": timestamp_strategy,
    "msg_type": st.sampled_from(["HEARTBEAT", "DATA", "REQUEST", "RESPONSE", "ERROR"]),
    "payload": payload_strategy,
})

@given(message_strategy)
def test_roundtrip_encoding(message):
    """Encoding then decoding yields the original message."""
    encoded = encode_message(message)
    decoded = decode_message(encoded)
    assert decoded == message

@given(message_strategy)
def test_encoding_is_deterministic(message):
    """Same message encodes to same bytes."""
    encoded1 = encode_message(message)
    encoded2 = encode_message(message)
    assert encoded1 == encoded2

@given(message_strategy)
def test_encoded_structure_is_valid_json(message):
    """Encoded message is valid JSON with required fields."""
    encoded = encode_message(message)
    data = json.loads(encoded.decode('utf-8'))
    assert "node_id" in data
    assert "timestamp" in data
    assert "msg_type" in data
    assert "payload" in data

@given(message_strategy)
def test_decode_rejects_malformed_data(message):
    """Decoding garbage raises MessageSchemaError."""
    # Corrupt the encoded message
    encoded = bytearray(encode_message(message))
    if len(encoded) > 0:
        encoded[0] ^= 0xFF
        with pytest.raises(MessageSchemaError):
            decode_message(bytes(encoded))

@given(st.binary(min_size=1, max_size=100))
def test_decode_rejects_random_binary(data):
    """Random binary data should never decode successfully."""
    with pytest.raises(MessageSchemaError):
        decode_message(data)